/**
 * GATE: card-dna-when-best — criterion N6.  →  `CARD-DNA-WHEN-BEST OK`
 *
 *   > **N6.** *"Section C renders Best-For chips with one-line explanations generated by the same
 *   > scoring engine, taken from its reason trace rather than written as UI copy."*
 *
 * MEASURES: 'render'. The claim is about what the chips say and where the words came from.
 *
 * ─────────────────────────────────────────────────────────────────────────────────────────────
 * "RATHER THAN WRITTEN AS UI COPY" IS THE WHOLE CRITERION, AND IT IS A NEGATIVE
 *
 * Spec §11's own example line is *"Lowest EUR cost of your 3 cards"* — a sentence that is only true
 * if something counted the cards and compared the costs. A component can produce that string in two
 * ways: by reading it out of the engine's `ReasonTrace`, or by writing it. The rendered pixels are
 * identical. The difference is whether the sentence stays true when the engine changes its mind.
 *
 * So this gate is built as **presence plus absence**, which is `D-018`'s rule:
 *
 *   · PRESENT — the explanation must be a `detail` string reachable from the scoring result's
 *     trace, and the suite must read it FROM the trace at run time rather than hardcoding it;
 *   · ABSENT — the explanation must not be in `src/i18n`. A string in the translation catalogue is
 *     UI copy by construction. That is not a stylistic objection: `arabicCoverage` walks the
 *     catalogue, so a sentence placed there acquires translations and a maintenance story, and the
 *     next person to edit the wording will edit it there and never touch the engine.
 *
 * A presence-only rule would be satisfied by a component that composed the sentence and happened to
 * match; an absence-only rule would be satisfied by a component that hardcoded it inline. Neither
 * alone is the criterion.
 *
 * ─────────────────────────────────────────────────────────────────────────────────────────────
 * THE SEAM, BECAUSE §C IS THE FIRST P5 SURFACE THAT NEEDS A REAL ENGINE RESULT
 *
 * §A reads stored values and §B reads a database. §C needs `scoreCards` to have run. B1 says a
 * surface never reaches an engine directly, and `src/surfaces/surfaceEngines.ts` calls each engine
 * exactly once per run — which is also what makes group A's *"in one run"* rule (§2 rule 10)
 * possible later. A §C that called the engine itself would produce a second scoring result, and two
 * results are exactly the disagreement `A1` exists to catch.
 *
 * ─────────────────────────────────────────────────────────────────────────────────────────────
 * AND THE READER STOPS LYING
 *
 * `agreementParticipants.ts` declares `card-dna-when-best` as `builtIn: 'PHASE-3'`. Once §C renders,
 * a `readCardDnaWhenBestChips` still returning `NOT_BUILT` makes that declaration false — and A1
 * would report the participant missing while it was on screen. So the reader must be real, and this
 * gate checks it.
 *
 * NEGATIVE CONTROL: replace an explanation with a hand-written sentence and watch this fail.
 */
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
import { ok, fail, requireJestCases } from '../lib/report.mjs';

export const CRITERIA = ['N6'];
export const SENTINEL = 'CARD-DNA-WHEN-BEST OK';
export const MEASURES = 'render';

const CHIPS = 'src/screens/cardDna/bestForChips.ts';
const SECTION = 'src/screens/cardDna/SectionCWhenBest.tsx';
const SCREEN = 'src/screens/cardDna/CardDnaScreen.tsx';
const SUITE = 'src/screens/cardDna/__tests__/cardDnaWhenBest.render.test.tsx';
const READERS = 'src/surfaces/__tests__/agreementReaders.tsx';
const SEAM = 'src/surfaces/surfaceEngines.ts';
const TRACE = 'src/engines/reasonTrace.ts';
const JEST_CONFIG = 'jest.config.cjs';
const RENDER_PROJECT = 'render';

const REQUIRED_CASES = [
  'renders a Best-For chip for each way this card ranks best',
  'renders each explanation exactly as the engine trace worded it',
  'renders no explanation when the trace offers none for that chip',
  'renders an honest empty state when nothing ranks this card',
  'takes its explanations from the engine rather than the translation catalogue',
];

/** Composition, in any of the forms that turn a trace string into a written sentence. */
const COMPOSES = [
  [/\bt\(\s*['"`][^'"`]{25,}/, 'passes a long sentence to t() — an explanation in the catalogue is UI copy by construction'],
  [/`[^`]*\$\{[^}]*\}[^`]*\b(cheapest|lowest|best|highest|cost|card)\b/i, 'builds an explanation with a template literal — N6 says taken from the trace, not composed'],
  [/\.detail\s*\+/, 'appends to a trace detail — the sentence stops being the engine\'s the moment anything is added to it'],
  [/\.detail\s*\.\s*(replace|slice|substring|toUpperCase|toLowerCase)\b/, 'rewrites a trace detail — selecting a step is allowed, editing its words is not'],
];

const stripComments = (src) =>
  src.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');

const renderConfigFor = (root) => {
  const configPath = join(root, JEST_CONFIG);
  if (!existsSync(configPath)) return { error: JEST_CONFIG + ' does not exist' };
  const config = createRequire(import.meta.url)(configPath);
  const projects = Array.isArray(config.projects) ? config.projects : [];
  const render = projects.find((p) => p && p.displayName === RENDER_PROJECT);
  if (!render) return { error: JEST_CONFIG + ' has no "' + RENDER_PROJECT + '" project' };
  return { config: { ...render, rootDir: root, testMatch: ['**/' + SUITE] } };
};

export const run = async ({ root }) => {
  for (const rel of [CHIPS, SECTION, SCREEN, SUITE, READERS, SEAM, TRACE]) {
    if (!existsSync(join(root, rel))) return fail(rel + ' does not exist — N6 has nothing to be about');
  }

  const chipsSrc = stripComments(readFileSync(join(root, CHIPS), 'utf8'));
  const sectionSrc = stripComments(readFileSync(join(root, SECTION), 'utf8'));
  const screenSrc = stripComments(readFileSync(join(root, SCREEN), 'utf8'));
  const suiteSrc = stripComments(readFileSync(join(root, SUITE), 'utf8'));
  const readersSrc = stripComments(readFileSync(join(root, READERS), 'utf8'));
  const problems = [];

  /* 1. PRESENCE — the explanation is a trace detail, and the chips module is where it is taken. */
  if (!/\.detail\b/.test(chipsSrc)) {
    problems.push(CHIPS + ' never reads a trace step\'s .detail — N6 requires the explanation to BE the engine\'s sentence, and there is no other place it can come from');
  }
  if (!/trace\b/.test(chipsSrc)) {
    problems.push(CHIPS + ' never touches a ReasonTrace — see ' + TRACE);
  }

  /* 2. ABSENCE — it is not composed, not templated, not edited, not in the catalogue (D-018). */
  for (const f of [{ n: CHIPS, s: chipsSrc }, { n: SECTION, s: sectionSrc }]) {
    for (const [re, why] of COMPOSES) {
      if (re.test(f.s)) problems.push(f.n + ' ' + why);
    }
  }

  /*
   * 2b. A CHIP LABEL IS NOT MACHINERY, AND A CHIP IS NOT A PARTICIPATION TROPHY.
   *
   * The first implementation set label to the trace step's `rule` — so the chip on screen read
   * 'product spec §20.1 effective cost' — with the raw cardId as fallback. N6 constrains where the
   * EXPLANATION comes from; the label is free to be an i18n string, and it should be one naming
   * what the card is best AT. A rule citation is the engine talking to its own author.
   *
   * And it emitted a chip for any card merely PRESENT in the ranking. A Best-For chip on a card
   * that came third is not a Best-For chip; §C has an honest empty state for exactly that case.
   */
  if (/label:\s*[A-Za-z0-9_.?]*\.rule\b/.test(chipsSrc)) {
    problems.push(CHIPS + " uses a trace step rule citation as a chip LABEL — that is internal machinery rendered to a user. The label may be i18n; only the explanation must come from the trace");
  }
  if (/label:\s*[A-Za-z0-9_.?]*\.cardId\b/.test(chipsSrc)) {
    problems.push(CHIPS + " falls back to a raw cardId as a chip label");
  }
  /* 3. THE SEAM. A §C that scored for itself would be a second scoring result, which is the
        disagreement A1 exists to catch — and §2 rule 10 measures agreement IN ONE RUN. */
  if (/from\s+'[^']*\/engines\//.test(sectionSrc) || /from\s+'[^']*\/engines\//.test(chipsSrc)) {
    problems.push('section C reaches an engine directly. B1: a surface reads through ' + SEAM + ', which calls each engine exactly once per run');
  }
  if (!/surfaces/.test(sectionSrc)) {
    problems.push(SECTION + ' does not read through the surfaces seam — §C is the first P5 surface that needs a real engine result, and it may not fetch its own');
  }

  /* 4. NO SCORING ON THE SURFACE. The engine ranks; the surface renders the ranking. */
  if (/\.sort\s*\(/.test(sectionSrc)) {
    problems.push(SECTION + ' sorts. The engine produces the ranking and the surface renders it — a screen that re-sorts is a second ranking');
  }

  /* 5. SECTION C IS REACHED. */
  if (!/SectionCWhenBest/.test(screenSrc)) {
    problems.push(SCREEN + ' does not render SectionCWhenBest — the chips exist and section C is still empty');
  }

  /* 6. THE READER STOPPED RETURNING NOT_BUILT, or the participants table is now false. */
  const readerBody = readersSrc.match(/export function readCardDnaWhenBestChips[\s\S]{0,400}?\n}/);
  const readerOneLiner = readersSrc.match(/export function readCardDnaWhenBestChips[^\n]*NOT_BUILT[^\n]*/);
  if (readerOneLiner || (readerBody && /return NOT_BUILT;\s*\n?}/.test(readerBody[0]) && !/render|getAllByTestId/.test(readerBody[0]))) {
    problems.push(
      READERS + ' still returns NOT_BUILT for readCardDnaWhenBestChips, but agreementParticipants.ts declares '
        + 'card-dna-when-best as builtIn PHASE-3. A1 would report the participant missing while it is on screen',
    );
  }

  /* 7. THE SUITE MUST READ THE SENTENCE FROM THE TRACE, not restate it. A hardcoded expectation
        passes whether the component quoted the engine or happened to type the same words. */
  if (!/\.detail\b/.test(suiteSrc)) {
    problems.push(
      SUITE + ' never reads a .detail from the trace. The explanation case has to take the string OUT of the '
        + 'engine result at run time and assert THAT appears — a hardcoded sentence passes equally well when the '
        + 'component composed its own and happened to match',
    );
  }

  if (problems.length) return fail(problems.join(' · '));

  const { config, error } = renderConfigFor(root);
  if (error) return fail(error);
  const { problems: caseProblems, summary } = requireJestCases(root, SUITE, REQUIRED_CASES, [
    '--config', JSON.stringify(config),
  ]);
  if (caseProblems.length) return fail(caseProblems.join(' · '), summary ?? undefined);
  if (!/Tests:\s+\d+ passed/.test(String(summary ?? ''))) {
    return fail('the suite reported no passing tests: ' + String(summary));
  }

  return ok(SENTINEL, [
    'CRITERION N6 — Card DNA §C, "when it\'s best to use".',
    'Every explanation IS a ReasonStep detail from the scoring engine, and the suite reads it out of',
    '  the trace at run time rather than restating it — a hardcoded sentence would pass equally well',
    '  against a component that composed its own and happened to match.',
    'Presence plus absence, which is D-018\'s rule: the sentence comes from the trace AND is not in',
    '  src/i18n, not templated, not appended to, not rewritten. A string in the catalogue is UI copy',
    '  by construction, and the next person to change the wording would change it there.',
    'Section C reads through ' + SEAM + ' and never an engine: a §C that scored for itself would be a',
    '  second scoring result, which is the disagreement A1 exists to catch.',
    'And readCardDnaWhenBestChips is real, so the participants table\'s builtIn: PHASE-3 is true.',
    REQUIRED_CASES.length + ' case(s) required BY NAME · ' + summary,
  ].join('\n'));
};
